mapper.select:
SELECT res_title, res_id
FROM Resource
WHERE course_id = #{courseId}

SELECT res_title, res_id
FROM Resource
WHERE user_id = #{userId}

mapper.update:
UPDATE Resource
SET res_title = #{resTitle}, res_description = #{resDescription}
WHERE res_id = #{resId};

mapper.select:
SELECT Resource.video_path
FROM Resource
WHERE video_file_name = #{videoFileName}

SELECT Resource.file_url
FROM Resource
WHERE file_name = #{fileName}

mapper.update:
UPDATE Resource
SET res_score = #{resScore}
WHERE res_id = #{resId}
